/// Initializes a 64-bit accumulator to 5, then runs two loops of 10 iterations each,
/// incrementing the accumulator by 1 on each iteration. Finally asserts that
/// the accumulator equals 25.
pub fn choose_odd() {
    let mut accum: u64 = 5;

    // First loop: i goes from 0 up to (but not including) 10
    let mut i: u64 = 0;
    while i < 10 {
        accum += 1;
        i += 1;
    }

    // Second loop: j goes from 0 up to (but not including) 10
    let mut j: u64 = 0;
    while j < 10 {
        accum += 1;
        j += 1;
    }

    // After 20 total increments, accum should be 5 + 20 = 25
    assert_eq!(accum, 25);
}

